// 2-joint servo arm: each knob drives one joint.
// Shoulder: pot on A0 -> SG90 on D9.  Elbow: pot on A1 -> SG90 on D10.
// Knob fully counter-clockwise = 0 deg, fully clockwise = 180 deg.
#include <Servo.h>

const uint8_t SHOULDER_POT = A0, ELBOW_POT = A1;
const uint8_t SHOULDER_PIN = 9, ELBOW_PIN = 10;
const int MIN_ANGLE = 0, MAX_ANGLE = 180;   // narrow these if your servos buzz at the end stops
const int DEADBAND = 2;                     // degrees; ignore pot noise smaller than this

Servo shoulder, elbow;
int shoulderAngle = -1, elbowAngle = -1;

// Average a few readings to tame wiper noise.
int readKnob(uint8_t pin) {
  long sum = 0;
  for (uint8_t i = 0; i < 8; i++) sum += analogRead(pin);
  return sum / 8;
}

int knobToAngle(int raw) {
  return constrain(map(raw, 0, 1023, MIN_ANGLE, MAX_ANGLE), MIN_ANGLE, MAX_ANGLE);
}

// Move only when the change exceeds the deadband, or the knob hits an end stop
// (so 0 and 180 are always reachable exactly).
bool update(Servo &s, int &current, int target) {
  bool atEnd = (target == MIN_ANGLE || target == MAX_ANGLE);
  if (current < 0 || abs(target - current) >= DEADBAND || (atEnd && target != current)) {
    current = target;
    s.write(current);
    return true;
  }
  return false;
}

void setup() {
  Serial.begin(115200);
  shoulder.attach(SHOULDER_PIN);
  elbow.attach(ELBOW_PIN);
  Serial.println("arm ready");
}

void loop() {
  bool moved = update(shoulder, shoulderAngle, knobToAngle(readKnob(SHOULDER_POT)));
  moved |= update(elbow, elbowAngle, knobToAngle(readKnob(ELBOW_POT)));
  if (moved) {
    Serial.print("shoulder=");
    Serial.print(shoulderAngle);
    Serial.print(" elbow=");
    Serial.println(elbowAngle);
  }
  delay(20);  // one servo frame
}

