args.content:
// 2-joint servo arm: each knob drives one joint.
// Shoulder: pot on A0 -> SG90 on D9.  Elbow: pot on A1 -> SG90 on D10.
// Knob fully counter-clockwise = 0 deg, fully clockwise = 180 deg.
#include <Servo.h>

const uint8_t SHOULDER_POT = A0, ELBOW_POT = A1;
const uint8_t SHOULDER_PIN = 9, ELBOW_PIN = 10;
const int MIN_ANGLE = 0, MAX_ANGLE = 180;   // narrow these if your servos buzz at the end stops
const int DEADBAND = 3;                     // degrees; ignore smaller wiggles (pot noise)
const float SMOOTHING = 0.25;               // 0..1, lower = smoother but slower

struct Joint {
  const char *name;
  uint8_t potPin, servoPin;
  Servo servo;
  float filtered;   // smoothed knob reading, 0..1023
  int angle;        // angle last written to the servo
};

Joint joints[2] = {
  {"shoulder", SHOULDER_POT, SHOULDER_PIN, Servo(), 0, -1},
  {"elbow",    ELBOW_POT,    ELBOW_PIN,    Servo(), 0, -1},
};

// Average a few readings to tame wiper noise.
int readKnob(uint8_t pin) {
  long sum = 0;
  for (uint8_t i = 0; i < 8; i++) sum += analogRead(pin);
  return sum / 8;
}

int knobToAngle(float raw) {
  int a = (int)(raw * (MAX_ANGLE - MIN_ANGLE) / 1023.0 + 0.5) + MIN_ANGLE;
  return constrain(a, MIN_ANGLE, MAX_ANGLE);
}

// Returns true when the servo was moved.
bool update(Joint &j) {
  int raw = readKnob(j.potPin);
  if (j.angle < 0) j.filtered = raw;                 // first reading: no lag
  else j.filtered += SMOOTHING * (raw - j.filtered); // exponential smoothing
  int target = knobToAngle(j.filtered);
  // Move when the change beats the deadband, or the knob reaches an end stop
  // (so exactly 0 and 180 are always reachable).
  bool atEnd = (target == MIN_ANGLE || target == MAX_ANGLE);
  if (j.angle < 0 || abs(target - j.angle) >= DEADBAND || (atEnd && target != j.angle)) {
    j.angle = target;
    j.servo.write(j.angle);
    return true;
  }
  return false;
}

void setup() {
  Serial.begin(115200);
  for (Joint &j : joints) j.servo.attach(j.servoPin);
  Serial.println("arm ready");
}

void loop() {
  bool moved = false;
  for (Joint &j : joints) moved |= update(j);
  if (moved) {
    Serial.print("shoulder=");
    Serial.print(joints[0].angle);
    Serial.print(" elbow=");
    Serial.println(joints[1].angle);
  }
  delay(20);  // one servo frame
}

